"""Human approval gate for destructive tool calls."""


def require_approval(action: str) -> bool:
    answer = input("approve %s? [y/N] " % action)
    return answer.strip().lower() == "y"


def run(action, execute):
    if not require_approval(action):
        raise PermissionError("refused by human")
    return execute(action)
